const b = ($input.first().json.body) || $input.first().json || {};
function pick(){ for (var i=0;i<arguments.length;i++){ var v=arguments[i]; if(v!==undefined&&v!==null&&v!=='') return v; } return undefined; }
var rawLine = String(pick(b.line_of_business, b.line, b.insurance_type, '')).toLowerCase();
var lineMap = { kfz:'car', auto:'car', car:'car', pkw:'car', privathaftpflicht:'liability', haftpflichtversicherung:'liability', private_liability:'liability', liability:'liability', haushalt:'home_contents', hausrat:'home_contents', household:'home_contents', contents:'home_contents', home_contents:'home_contents', rechtsschutz:'legal', legal:'legal', legal_protection:'legal', leben:'life', life:'life', risikoleben:'life', vorsorge:'life' };
var line = lineMap[rawLine] || 'other';
var CATALOG = [
 {ProductCode:'CAR-LIAB-STD',LineOfBusiness:'car',ProductName:'Unica Kfz Haftpflicht',TargetSegment:'Standard private drivers, liability-only',EligibilityRules:{min_driver_age:18},indicative_base:480},
 {ProductCode:'CAR-TK-COMFORT',LineOfBusiness:'car',ProductName:'Unica Kfz Komfort (Haftpflicht + Teilkasko)',TargetSegment:'Mid-value vehicles, partial cover',EligibilityRules:{min_driver_age:21,max_vehicle_age_years:12},indicative_base:760},
 {ProductCode:'CAR-VK-PREMIUM',LineOfBusiness:'car',ProductName:'Unica Kfz Premium (Haftpflicht + Vollkasko)',TargetSegment:'New/financed vehicles, full protection',EligibilityRules:{min_driver_age:23,max_vehicle_age_years:8},indicative_base:1180},
 {ProductCode:'LIAB-SINGLE',LineOfBusiness:'liability',ProductName:'Unica Privathaftpflicht Single',TargetSegment:'Single private individual',EligibilityRules:{household:'single'},indicative_base:70},
 {ProductCode:'LIAB-FAMILY',LineOfBusiness:'liability',ProductName:'Unica Privathaftpflicht Familie',TargetSegment:'Families / couples',EligibilityRules:{household:'family'},indicative_base:95},
 {ProductCode:'HC-STD',LineOfBusiness:'home_contents',ProductName:'Unica Haushalt',TargetSegment:'Renters and owners insuring contents',EligibilityRules:{occupancy:['owner','tenant']},indicative_base:0.0016},
 {ProductCode:'HC-PLUS',LineOfBusiness:'home_contents',ProductName:'Unica Haushalt Plus (inkl. Glas & Fahrrad)',TargetSegment:'Higher-value contents, extra perils',EligibilityRules:{occupancy:['owner','tenant']},indicative_base:0.0022},
 {ProductCode:'LEGAL-PRIVATE',LineOfBusiness:'legal',ProductName:'Unica Privat-Rechtsschutz',TargetSegment:'Private legal protection',EligibilityRules:{},indicative_base:230},
 {ProductCode:'LEGAL-COMBO',LineOfBusiness:'legal',ProductName:'Unica Rechtsschutz Kombi (Privat + Verkehr + Wohnen)',TargetSegment:'Comprehensive legal protection',EligibilityRules:{},indicative_base:360},
 {ProductCode:'LIFE-TERM-STD',LineOfBusiness:'life',ProductName:'Unica Risikoleben (Term)',TargetSegment:'Income/family protection, fixed term',EligibilityRules:{min_age:18,max_age:65},indicative_base:0.0009},
 {ProductCode:'LIFE-VORSORGE',LineOfBusiness:'life',ProductName:'Unica Leben Vorsorge (Erleben)',TargetSegment:'Long-term provision + cash value',EligibilityRules:{min_age:18,max_age:60},indicative_base:0.0021}
];
var eligible = CATALOG.filter(function(p){ return p.LineOfBusiness === line; });
var lead = { name: pick(b.name,b.full_name), phone: pick(b.phone,b.phone_number), email: b.email, region: pick(b.region,'land'), driver_age: b.driver_age, power_kw: b.power_kw, coverage: pick(b.coverage,'haftpflicht'), bonus_malus: b.bonus_malus, household: pick(b.household,b.household_size,'single'), contents_value: pick(b.contents_value,b.sum_insured), sum_assured: pick(b.sum_assured,b.coverage_amount), term_years: b.term_years, tobacco: b.tobacco, consent: pick(b.consent_recording,b.consent,false) };
var slim = eligible.map(function(p){ return {ProductCode:p.ProductCode,ProductName:p.ProductName,TargetSegment:p.TargetSegment,EligibilityRules:p.EligibilityRules}; });
var prompt = 'Lead JSON: ' + JSON.stringify(lead) + ' || Eligible products JSON: ' + JSON.stringify(slim) + ' || Task: choose the single best ProductCode for this retail lead. If mandatory info is missing or two products fit equally, lower confidence and list missing_fields. Reply with strict JSON only.';
return [{ json: { line: line, lead: lead, eligible: eligible, llm_prompt: prompt } }];

var out = $json.output || $json || {};
var prep = $('Validate & Load Catalog').first().json;
var eligible = prep.eligible || [];
var lead = prep.lead || {};
var line = prep.line;
var code = out.selected_product_code || out.ProductCode || (eligible[0] && eligible[0].ProductCode);
var product = eligible.filter(function(p){ return p.ProductCode===code; })[0] || eligible[0] || null;
function f(x,d){ return (x===undefined||x===null||x==='')?d:Number(x); }
var mid = 0;
if (product){
  var base = product.indicative_base;
  if (line==='car'){
    var a=f(lead.driver_age,40); var ageF = a<23?1.45:(a<30?1.18:(a<65?1.0:1.12));
    var powF = 1 + Math.max(0,(f(lead.power_kw,85)-70))*0.006;
    var regF = ({wien:1.15,graz:1.06,linz:1.04,land:0.95})[String(lead.region||'land')] || 1.0;
    var bm = Math.max(0.5,Math.min(1.8,f(lead.bonus_malus,1.0)));
    mid = base*ageF*powF*regF*bm;
  } else if (line==='liability'){
    mid = base;
  } else if (line==='home_contents'){
    mid = f(lead.contents_value,40000)*base;
  } else if (line==='legal'){
    mid = base;
  } else if (line==='life'){
    var tob = lead.tobacco ? 1.6 : 1.0; mid = f(lead.sum_assured,100000)*base*tob;
  } else { mid = base; }
}
var low = Math.round(mid*0.82/10)*10, high = Math.round(mid*1.18/10)*10;
if (product && low < 10) low = 10;
var conf = Number(out.confidence!==undefined?out.confidence:0.7);
var missing = out.missing_fields || [];
var status = 'NeedsReview';
if (!product) status='Disqualified';
else if (conf>=0.8 && (!missing || missing.length===0)) status='Qualified';
var resp = {
  status: status,
  line: line,
  recommended_product: product?{ProductCode:product.ProductCode,ProductName:product.ProductName}:null,
  indicative_range: product?{low:low,high:high,currency:'EUR',per:'year'}:null,
  rationale: out.rationale || (product?'':'Line not offered for retail (only car, liability, home_contents, legal, life).'),
  lead_score: (out.lead_score!==undefined?out.lead_score:null),
  confidence: conf,
  missing_fields: missing,
  next_step: status==='Qualified'?'offer_consultation_booking':(status==='Disqualified'?'inform_not_offered':'human_review'),
  disclaimer: 'Indikativer Richtwert, kein verbindliches Angebot. Ein Berater prueft den finalen Tarif.'
};
return [{ json: resp }];
